// Removes maps from the CDN that were never used: neither played in a game
// (replays) nor referenced in maps-metadata, as listed in the file generated by
// gen_used_maps.ts.
//
// It lists `from_name/map/*` keys in the assets KV and objects in all R2
// buckets, computes what to delete and writes the plan to a file. Nothing is
// deleted unless --no-dry-run is passed. In that case the KV keys are deleted
// first, so maps stop being served by /find and /download, and then the R2
// objects only referenced by the deleted keys.
//
// Uses the same environment variables as cacher:
//   CF_ACCOUNT_ID, CF_KV_NAMESPACE_ID, CF_KV_API_TOKEN,
//   CF_R2_ACCESS_KEY_ID, CF_R2_ACCESS_KEY_SECRET, CF_R2_BUCKETS
//
// Usage:
//   node cleanup_cdn_maps.ts --used-maps used_maps.json [--plan-out cleanup_plan.json] [--delete-orphans] [--no-dry-run]

import * as fs from 'node:fs/promises';
import { parseArgs } from 'node:util';
import { setTimeout as sleep } from 'node:timers/promises';
import { S3Client, ListObjectsV2Command, DeleteObjectsCommand } from '@aws-sdk/client-s3';
import * as lib from '../lib/index.ts';
import type { UsedMapsFile } from './gen_used_maps.ts';

const KV_PREFIX = 'from_name/';
const KV_MAP_PREFIX = lib.getKVKey('map', '');
const KV_LIST_LIMIT = 1000;
const KV_BULK_GET_LIMIT = 100;
const KV_BULK_DELETE_LIMIT = 10000;
const R2_DELETE_LIMIT = 1000;
// Cacher uploads to R2 before writing KV, so a fresh object without a KV key
// may be an upload in progress.
const ORPHAN_MIN_AGE_MS = 24 * 60 * 60 * 1000;

function env(name: string): string {
    const v = process.env[name];
    if (!v) throw new Error(`Required environment variable ${name} not set`);
    return v;
}

class KV {
    private base: string;
    private token: string;

    constructor() {
        const apiBase = process.env.CF_API_BASE ?? 'https://api.cloudflare.com/client/v4';
        this.base = `${apiBase}/accounts/${env('CF_ACCOUNT_ID')}/storage/kv/namespaces/${env('CF_KV_NAMESPACE_ID')}`;
        this.token = env('CF_KV_API_TOKEN');
    }

    private async call(method: string, path: string, body?: unknown): Promise<any> {
        for (let attempt = 0; ; ++attempt) {
            const resp = await fetch(`${this.base}${path}`, {
                method,
                headers: {
                    'Authorization': `Bearer ${this.token}`,
                    ...(body !== undefined ? { 'Content-Type': 'application/json' } : {}),
                },
                body: body !== undefined ? JSON.stringify(body) : undefined,
            });
            if ((resp.status === 429 || resp.status >= 500) && attempt < 5) {
                await resp.body?.cancel();
                await sleep(1000 * 2 ** attempt);
                continue;
            }
            const json = await resp.json() as any;
            if (!resp.ok || !json.success) {
                throw new Error(`KV ${method} ${path} failed with ${resp.status}: ${JSON.stringify(json.errors ?? json)}`);
            }
            return json;
        }
    }

    async listKeys(prefix: string): Promise<string[]> {
        const keys: string[] = [];
        let cursor = '';
        do {
            const params = new URLSearchParams({ prefix, limit: String(KV_LIST_LIMIT) });
            if (cursor) params.set('cursor', cursor);
            const json = await this.call('GET', `/keys?${params}`);
            keys.push(...(json.result as Array<{ name: string }>).map(k => k.name));
            cursor = json.result_info?.cursor ?? '';
        } while (cursor);
        return keys;
    }

    async bulkGet(keys: string[]): Promise<Map<string, string | null>> {
        const values = new Map<string, string | null>();
        for (let i = 0; i < keys.length; i += KV_BULK_GET_LIMIT) {
            const batch = keys.slice(i, i + KV_BULK_GET_LIMIT);
            const json = await this.call('POST', '/bulk/get', { keys: batch, type: 'text' });
            for (const k of batch) values.set(k, json.result.values[k] ?? null);
        }
        return values;
    }

    async bulkDelete(keys: string[]) {
        for (let i = 0; i < keys.length; i += KV_BULK_DELETE_LIMIT) {
            const batch = keys.slice(i, i + KV_BULK_DELETE_LIMIT);
            const json = await this.call('POST', '/bulk/delete', batch);
            const failed: string[] = json.result?.unsuccessful_keys ?? [];
            if (failed.length > 0) {
                throw new Error(`KV bulk delete failed for ${failed.length} keys: ${failed.join(', ')}`);
            }
            console.log(`Deleted ${batch.length} KV keys`);
        }
    }
}

interface R2Object {
    key: string,
    size: number,
    lastModified?: Date,
}

function r2Client(): S3Client {
    return new S3Client({
        region: 'auto',
        endpoint: process.env.CF_R2_ENDPOINT ?? `https://${env('CF_ACCOUNT_ID')}.r2.cloudflarestorage.com`,
        forcePathStyle: !!process.env.CF_R2_ENDPOINT,
        credentials: {
            accessKeyId: env('CF_R2_ACCESS_KEY_ID'),
            secretAccessKey: env('CF_R2_ACCESS_KEY_SECRET'),
        },
    });
}

async function listR2Objects(client: S3Client, bucket: string): Promise<R2Object[]> {
    const objects: R2Object[] = [];
    let token: string | undefined;
    do {
        const resp = await client.send(new ListObjectsV2Command({ Bucket: bucket, ContinuationToken: token }));
        for (const o of resp.Contents ?? []) {
            objects.push({ key: o.Key!, size: o.Size ?? 0, lastModified: o.LastModified });
        }
        token = resp.IsTruncated ? resp.NextContinuationToken : undefined;
    } while (token);
    return objects;
}

async function deleteR2Objects(client: S3Client, bucket: string, keys: string[]) {
    for (let i = 0; i < keys.length; i += R2_DELETE_LIMIT) {
        const batch = keys.slice(i, i + R2_DELETE_LIMIT);
        const resp = await client.send(new DeleteObjectsCommand({
            Bucket: bucket,
            Delete: { Objects: batch.map(Key => ({ Key })), Quiet: true },
        }));
        if (resp.Errors && resp.Errors.length > 0) {
            throw new Error(`R2 delete in ${bucket} failed for ${resp.Errors.length} objects: `
                + resp.Errors.map(e => `${e.Key}: ${e.Code} ${e.Message}`).join(', '));
        }
        console.log(`Deleted ${batch.length} objects from ${bucket}`);
    }
}

// Returns R2 object keys (md5) the asset is served from.
function r2KeysOfAsset(asset: lib.SpringFilesAsset): string[] {
    return (asset.mirrors ?? [])
        .map(m => /^file\/([^/]+)\//.exec(m)?.[1])
        .filter((k): k is string => k !== undefined);
}

interface KVEntry {
    key: string,
    raw: string | null,
    asset?: lib.SpringFilesAsset,
    r2Keys: string[],
}

interface BucketPlan {
    bucket: string,
    objects: number,
    bytes: number,
    delete: R2Object[],
    // Objects not referenced by any KV key.
    orphans: R2Object[],
    // R2 keys referenced by kept KV keys but missing in the bucket.
    missing: string[],
}

function sumSize(objs: R2Object[]) {
    return objs.reduce((s, o) => s + o.size, 0);
}

function fmtBytes(n: number) {
    return `${(n / 2 ** 30).toFixed(2)} GiB`;
}

async function main() {
    const { values } = parseArgs({
        options: {
            'used-maps': { type: 'string' },
            'plan-out': { type: 'string', default: 'cleanup_plan.json' },
            'delete-orphans': { type: 'boolean', default: false },
            'dry-run': { type: 'boolean', default: true },
            'help': { type: 'boolean', short: 'h' },
        },
        allowNegative: true,
    });
    if (values.help || !values['used-maps']) {
        console.error('Usage: node cleanup_cdn_maps.ts --used-maps used_maps.json [--plan-out cleanup_plan.json] [--delete-orphans] [--no-dry-run]');
        process.exit(values.help ? 0 : 2);
    }
    const dryRun = values['dry-run'];

    const usedFile = JSON.parse(await fs.readFile(values['used-maps'], 'utf8')) as UsedMapsFile;
    if (!Array.isArray(usedFile.maps) || usedFile.maps.length === 0) {
        throw new Error(`${values['used-maps']} has no maps, refusing to continue`);
    }
    // Springnames are matched case insensitively: when in doubt, keep.
    const used = new Set(usedFile.maps.map(m => m.springname.toLowerCase()));
    console.log(`Loaded ${used.size} used maps from ${values['used-maps']} (generated ${usedFile.generated_at})`);

    // KV
    const kv = new KV();
    const keys = await kv.listKeys(KV_PREFIX);
    const values_ = await kv.bulkGet(keys);
    const entries: KVEntry[] = keys.map(key => {
        const raw = values_.get(key) ?? null;
        let asset: lib.SpringFilesAsset | undefined;
        try {
            asset = raw !== null ? JSON.parse(raw) : undefined;
        } catch {
            console.warn(`KV key ${key} has non-JSON value`);
        }
        return { key, raw, asset, r2Keys: asset ? r2KeysOfAsset(asset) : [] };
    });
    const mapEntries = entries.filter(e => e.key.startsWith(KV_MAP_PREFIX));
    const isUsed = (e: KVEntry) =>
        used.has(e.key.slice(KV_MAP_PREFIX.length).toLowerCase())
        || (typeof e.asset?.springname === 'string' && used.has(e.asset.springname.toLowerCase()));
    const kvDelete = mapEntries.filter(e => !isUsed(e));
    const kvDeleteSet = new Set(kvDelete.map(e => e.key));
    const kvKeep = entries.filter(e => !kvDeleteSet.has(e.key));
    const keptMapCount = mapEntries.length - kvDelete.length;
    if (mapEntries.length > 0 && keptMapCount === 0) {
        throw new Error('None of the maps in KV is in the used maps list, refusing to continue');
    }

    const keptR2Keys = new Set(kvKeep.flatMap(e => e.r2Keys));
    const allR2Keys = new Set(entries.flatMap(e => e.r2Keys));
    const deletedR2Keys = new Set(kvDelete.flatMap(e => e.r2Keys).filter(k => !keptR2Keys.has(k)));

    // R2
    const r2 = r2Client();
    const buckets = env('CF_R2_BUCKETS').split(',').map(b => b.trim()).filter(b => b);
    const now = Date.now();
    const bucketPlans: BucketPlan[] = [];
    for (const bucket of buckets) {
        const objects = await listR2Objects(r2, bucket);
        const present = new Set(objects.map(o => o.key));
        const orphans = objects.filter(o => !allR2Keys.has(o.key));
        const orphansToDelete = values['delete-orphans']
            ? orphans.filter(o => o.lastModified && now - o.lastModified.getTime() > ORPHAN_MIN_AGE_MS)
            : [];
        bucketPlans.push({
            bucket,
            objects: objects.length,
            bytes: sumSize(objects),
            delete: [...objects.filter(o => deletedR2Keys.has(o.key)), ...orphansToDelete],
            orphans,
            missing: [...keptR2Keys].filter(k => !present.has(k)).sort(),
        });
    }

    // Plan
    const plan = {
        generated_at: new Date().toISOString(),
        dry_run: dryRun,
        used_maps: { file: values['used-maps'], generated_at: usedFile.generated_at, count: used.size },
        kv: {
            keys: keys.length,
            map_keys: mapEntries.length,
            keep_map_keys: keptMapCount,
            // Full values, so deleted keys can be restored if needed.
            delete: kvDelete.map(e => ({ key: e.key, value: e.raw })),
        },
        r2: bucketPlans,
    };
    await fs.writeFile(values['plan-out'], JSON.stringify(plan, null, 2) + '\n');

    console.log(`KV: ${keys.length} keys, ${mapEntries.length} maps: keep ${keptMapCount}, delete ${kvDelete.length}`);
    for (const b of bucketPlans) {
        console.log(`R2 ${b.bucket}: ${b.objects} objects (${fmtBytes(b.bytes)}): `
            + `delete ${b.delete.length} (${fmtBytes(sumSize(b.delete))}), `
            + `orphans ${b.orphans.length} (${fmtBytes(sumSize(b.orphans))}${values['delete-orphans'] ? '' : ', kept, use --delete-orphans'}), `
            + `missing for kept keys ${b.missing.length}`);
    }
    console.log(`Plan written to ${values['plan-out']}`);

    if (dryRun) {
        console.log('Dry run, nothing deleted. Pass --no-dry-run to delete.');
        return;
    }
    if (kvDelete.length > 0) {
        await kv.bulkDelete(kvDelete.map(e => e.key));
    }
    for (const b of bucketPlans) {
        if (b.delete.length > 0) {
            await deleteR2Objects(r2, b.bucket, b.delete.map(o => o.key));
        }
    }
    console.log('Done.');
}

await main();
